    cnt={c:sum(r.count(c) for r in g) for c in set(x for r in g for x in r)}
    bg=max(cnt,key=cnt.get)
    H,W=len(g),len(g[0]);seen=[[False]*W for _ in range(H)];res=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and not seen[i][j]:
                col=g[i][j];dq=deque([(i,j)]);seen[i][j]=True;cells=[]
                while dq:
                    y,x=dq.popleft();cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]==col:
                            seen[ny][nx]=True;dq.append((ny,nx))
                ys=[c[0] for c in cells];xs=[c[1] for c in cells]
                res.append((col,len(cells),(max(ys)-min(ys)+1)*(max(xs)-min(xs)+1)))
    return res
